create table market_listings(id uuid primary key,public_id varchar(30) not null unique,seller_id uuid not null references users(id),oil_type varchar(30) not null,volume_liters int not null,grade_label varchar(2) not null,price_per_liter numeric(10,2) not null,status varchar(30) not null,city varchar(100) not null,state varchar(100) not null,region varchar(100),collection_frequency varchar(30),available_from date,seller_ref varchar(40) not null,quality_notes text,moisture_content varchar(30),acid_value varchar(40),ffa varchar(30),iodine_value varchar(30),listing_date date not null,min_order_liters int not null,created_at timestamptz not null default now());
create table buyer_orders(id uuid primary key,public_id varchar(30) not null unique,buyer_id uuid not null references users(id),listing_id uuid not null references market_listings(id),volume_liters int not null,price_per_liter numeric(10,2) not null,total_amount numeric(12,2) not null,status varchar(30) not null,delivery_address varchar(700) not null,notes text,pickup_date date,delivery_date date,payment_due date,invoice_number varchar(50),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_buyer_orders_buyer on buyer_orders(buyer_id);
create table buyer_payments(id uuid primary key,public_id varchar(30) not null unique,buyer_id uuid not null references users(id),order_id uuid not null references buyer_orders(id),amount numeric(12,2) not null,status varchar(30) not null,due_date date,settled_date date,reference varchar(60),invoice_number varchar(50),created_at timestamptz not null default now());
create index idx_buyer_payments_buyer on buyer_payments(buyer_id);